import{_ as l,a0 as r,w as o,s as m,I as a,x as i,a1 as n,A as p,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Linux 上的科學圖像處理 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 上的科學圖像處理 | LCTT (201711) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 上的科學圖像處理 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 上的科學圖像處理 | LCTT (201711) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201711/20171017 Image Processing on Linux","title":"Linux 上的科學圖像處理","tag":"201711","desc":""},"relativePath":"201711/20171017 Image Processing on Linux.md","filePath":"[post].md"}'),u={name:"201711/20171017 Image Processing on Linux.md"};function g(f,e,x,j,d,w){const t=r("Link");return o(),m("div",null,[e[16]||(e[16]=a("h1",{id:"linux-上的科學圖像處理",tabindex:"-1"},[i("Linux 上的科學圖像處理 "),a("a",{class:"header-anchor",href:"#linux-上的科學圖像處理","aria-label":"Permalink to “Linux 上的科學圖像處理”"},"​")],-1)),a("p",null,[e[1]||(e[1]=i("在顯示你的數據和工作方面我發現了幾個科學軟件，但是我不會涉及太多方面。因此在這篇文章中，我將談到一款叫 ImageJ 的熱門圖像處理軟件。特別的，我會介紹 ",-1)),n(t,{href:"https://imagej.net/Fiji"},{default:p(()=>[...e[0]||(e[0]=[i("Fiji",-1)])]),_:1}),e[2]||(e[2]=i("，這是一款綁定了一系列用於科學圖像處理插件的 ImageJ 軟件。",-1))]),e[17]||(e[17]=s('<p>Fiji 這個名字是一個循環縮略詞，很像 GNU 。代表着 “Fiji Is Just ImageJ”。 ImageJ 是科學研究領域進行圖像分析的實用工具 —— 例如你可以用它來辨認航拍風景圖中樹的種類。 ImageJ 能劃分物品種類。它以插件架構製成，海量插件可供選擇以提升使用靈活度。</p><p>首先是安裝 ImageJ （或 Fiji）。大多數的 ImageJ 發行版都可有該軟件包。你願意的話，可以以這種方式安裝它，然後根據你的研究安裝所需的獨立插件。另一種選擇是安裝 Fiji 的同時獲取最常用的插件。不幸的是，大多數 Linux 發行版的軟件中心不會有可用的 Fiji 安裝包。幸而，官網上的簡單安裝文件是可以使用的。這是一個 zip 文件，包含了運行 Fiji 需要的所有文件目錄。第一次啓動時，你只會看到一個列出了菜單項的工具欄。（圖 1）</p><p><img src="http://www.linuxjournal.com/files/linuxjournal.com/ufiles/imagecache/large-550px-centered/u1000009/12172fijif1.png" alt=""></p><p><em>圖 1. 第一次打開 Fiji 有一個最小化的界面。</em></p><p>如果你沒有備好圖片來練習使用 ImageJ ，Fiji 安裝包包含了一些示例圖片。點擊“File”-&gt;“Open Samples”的下拉菜單選項（圖 2）。這些示例包含了許多你可能有興趣做的任務。</p><p><img src="http://www.linuxjournal.com/files/linuxjournal.com/ufiles/imagecache/large-550px-centered/u1000009/12172fijif2.jpg" alt=""></p><p><em>圖 2. 案例圖片可供學習使用 ImageJ。</em></p><p>如果你安裝了 Fiji，而不是單純的 ImageJ ，那麼大量插件也會被安裝。首先要注意的是自動更新器插件。每次打開 ImageJ ，該插件將聯網檢驗 ImageJ 和已安裝插件的更新。</p><p>所有已安裝的插件都在“插件”菜單項中可選。一旦你安裝了很多插件，列表會變得冗雜，所以需要精簡你選擇的插件。你想手動更新的話，點擊“Help”-&gt;“Update Fiji” 菜單項強制檢測並獲取可用更新的列表（圖 3）。</p><p><img src="http://www.linuxjournal.com/files/linuxjournal.com/ufiles/imagecache/large-550px-centered/u1000009/12172fijif3.png" alt=""></p><p><em>圖 3. 強制手動檢測可用更新。</em></p><p>那麼，現在，用 Fiji/ImageJ 可以做什麼呢？舉一例，統計圖片中的物品數。你可以通過點擊“File”-&gt;“Open Samples”-&gt;“Embryos”來載入示例。</p><p><img src="http://www.linuxjournal.com/files/linuxjournal.com/ufiles/imagecache/large-550px-centered/u1000009/12172fijif4.jpg" alt=""></p><p><em>圖 4. 用 ImageJ 算出圖中的物品數。</em></p><p>第一步給圖片設定比例，這樣你可以告訴 ImageJ 如何判別物品。首先，選擇在工具欄選擇線條按鈕。然後選擇“Analyze”-&gt;“Set Scale”，然後就會設置比例尺包含的像素點個數(圖 5)。你可以設置“known distance ”為 100，單元為“um”。</p><p><img src="http://www.linuxjournal.com/files/linuxjournal.com/ufiles/imagecache/large-550px-centered/u1000009/12172fijif5.png" alt=""></p><p><em>圖 5. 很多圖片分析任務需要對圖片設定一個範圍。</em></p><p>接下來的步驟是簡化圖片內的信息。點擊“Image”-&gt;“Type”-&gt;“8-bit”來減少信息量到 8 比特灰度圖片。要分隔獨立物體點擊“Process”-&gt;“Binary”-&gt;“Make Binary”以自動設置圖片門限。(圖 6)。</p><p><img src="http://www.linuxjournal.com/files/linuxjournal.com/ufiles/imagecache/large-550px-centered/u1000009/12172fijif6.png" alt=""></p><p><em>圖 6. 有些工具可以自動完成像門限一樣的任務。</em></p><p>圖片內的物品計數前，你需要移除像比例尺之類的人工操作。可以用矩形選擇工具來選中它並點擊“Edit”-&gt;“Clear”來完成這項操作。現在你可以分析圖片看看這裏是啥物體。</p><p>確保圖中沒有區域被選中，點擊“Analyze”-&gt;“Analyze Particles”來彈出窗口來選擇最小尺寸，這決定了最後的圖片會展示什麼（圖 7）。</p><p><img src="http://www.linuxjournal.com/files/linuxjournal.com/ufiles/imagecache/large-550px-centered/u1000009/12172fijif7.png" alt=""></p><p>*圖 7. 你可以通過確定最小尺寸生成一個縮減過的圖片。 *</p><p>圖 8 在總結窗口展示了一個概覽。每個最小點也有獨立的細節窗口。</p><p><img src="http://www.linuxjournal.com/files/linuxjournal.com/ufiles/imagecache/large-550px-centered/u1000009/12172fijif8.png" alt=""></p><p><em>圖 8. 包含了已知最小點總覽清單的輸出結果。</em></p><p>當你有一個分析程序可以工作於給定圖片類型，你通常需要將相同的步驟應用到一系列圖片當中。這可能數以千計，你當然不會想對每張圖片手動重複操作。這時候，你可以集中必要步驟到宏，這樣它們可以被應用多次。點擊插件-&gt;“Macros”-&gt;“Record”，彈出一個新的窗口記錄你隨後的所有命令。所有步驟完成，你可以將之保存為一個宏文件，並且通過點擊“Plugins”-&gt;“Macros”-&gt;“Run”來在其它圖片上重複運行。</p><p>如果你有非常特定的工作步驟，你可以簡單地打開宏文件並手動編輯它，因為它是一個簡單的文本文件。事實上有一套完整的宏語言可供你更加充分地控制圖片處理過程。</p><p>然而，如果你有真的有非常多的系列圖片需要處理，這也將是冗長乏味的工作。這種情況下，前往“Process”-&gt;“Batch”-&gt;“Macro”，會彈出一個你可以設置批量處理工作的新窗口（圖 9）。</p><p><img src="http://www.linuxjournal.com/files/linuxjournal.com/ufiles/imagecache/large-550px-centered/u1000009/12172fijif9.png" alt=""></p><p><em>圖 9. 對批量輸入的圖片用單一命令運行宏。</em></p><p>這個窗口中，你能選擇應用哪個宏文件、輸入圖片所在的源目錄和你想寫入輸出圖片的輸出目錄。也可以設置輸出文件格式，及通過文件名篩選輸入圖片中需要使用的。萬事具備之後，點擊窗口下方的的“Process”按鈕開始批量操作。</p><p>若這是會重複多次的工作，你可以點擊窗口底部的“Save”按鈕保存批量處理到一個文本文件。點擊也在窗口底部的“Open”按鈕重新加載相同的工作。這個功能可以使得研究中最冗餘部分自動化，這樣你就可以在重點放在實際的科學研究中。</p><p>考慮到單單是 ImageJ 主頁就有超過 500 個插件和超過 300 種宏可供使用，簡短起見，我只能在這篇短文中提出最基本的話題。幸運的是，還有很多專業領域的教程可供使用，項目主頁上還有關於 ImageJ 核心的非常棒的文檔。如果你覺得這個工具對研究有用，你研究的專業領域也會有很多信息指引你。</p><hr><p>作者簡介：</p><p>Joey Bernard 有物理學和計算機科學的相關背景。這對他在新不倫瑞克大學當計算研究顧問的日常工作大有裨益。他也教計算物理和並行程序規劃。</p><hr>',39)),a("p",null,[e[4]||(e[4]=i("via: ",-1)),n(t,{href:"https://www.linuxjournal.com/content/image-processing-linux"},{default:p(()=>[...e[3]||(e[3]=[i("https://www.linuxjournal.com/content/image-processing-linux",-1)])]),_:1})]),a("p",null,[e[8]||(e[8]=i("作者：",-1)),n(t,{href:"https://www.linuxjournal.com/users/joey-bernard"},{default:p(()=>[...e[5]||(e[5]=[i("Joey Bernard",-1)])]),_:1}),e[9]||(e[9]=i(" 譯者：",-1)),n(t,{href:"https://github.com/XYenChi"},{default:p(()=>[...e[6]||(e[6]=[i("XYenChi",-1)])]),_:1}),e[10]||(e[10]=i(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:p(()=>[...e[7]||(e[7]=[i("wxy",-1)])]),_:1})]),a("p",null,[e[13]||(e[13]=i("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[11]||(e[11]=[i("LCTT",-1)])]),_:1}),e[14]||(e[14]=i(" 原創編譯，",-1)),n(t,{href:"https://linux.cn/"},{default:p(()=>[...e[12]||(e[12]=[i("Linux中國",-1)])]),_:1}),e[15]||(e[15]=i(" 榮譽推出",-1))])])}const L=l(u,[["render",g]]);export{T as __pageData,L as default};
